command:
$HistoryLength=0;root=Directory[];checks=<||>;
gate[name_,test_]:=If[TrueQ[test],AssociateTo[checks,name->True];Print["PASS: ",name],Print["FAIL: ",name];Quit[1]];
relative="Hgg/s08_additive_reconstruction_result/s08_result.wl";path=FileNameJoin[{root,relative}];
receipt=Import[FileNameJoin[{DirectoryName[path],"s08_execution.json"}],"RawJSON"];
gate["accepted complete actual reconstruction proof",TrueQ[receipt["passed"]]&&receipt["result_sha256"][relative]===IntegerString[FileHash[path,"SHA256"],16,64]];
proof=Get[path];
gate["exact accepted reconstruction identity",proof["Schema"]==="polarized-sidis-additive-reconstruction-v1"&&
 proof["NativeVersions"][[1]]===$Version&&proof["ExactDifference"]===0&&TrueQ[proof["OriginalFailureReproduced"]]&&
 TrueQ[proof["OwnAcceptedComparison"]]&&And@@Values[proof["Checks"]]];
DownValues[zero]=Last[proof["AlgebraDefinitions"]];original=DownValues[zero];
DownValues[polynomialAdditivePieces]=proof["AlgebraDefinitions"][[4]];
sharedPath=FileNameJoin[{root,"Hgg","s08_shared_piece_cache_result","s08_result.wl"}];
gate["same accepted own comparison",FileHash[sharedPath,"SHA256"]===proof["SharedProofHash"]];shared=Get[sharedPath];
families=Get[FileNameJoin[{root,"Hgg","s08_mapping_inputs_result","s08_component_0008.wl"}]]["Families"];familyNames=Keys[families];
ownEquation=shared["ActualInput"]["Equation"];ownPieces=polynomialAdditivePieces[ownEquation];
gate["own additive pieces unchanged",ownPieces===shared["ActualInput"]["Pieces"]];
{ownOriginalSeconds,ownOriginal}=AbsoluteTiming[zero[Total[ownPieces]-ownEquation]];
actual=proof["ActualInput"];
gate["actual complete additive pieces unchanged",polynomialAdditivePieces[actual["Equation"]]===actual["Pieces"]];
difference=Total[actual["Pieces"]]-actual["Equation"];
gate["cached identity is a bounded literal expression",ByteCount[difference]<64*1024^2&&FreeQ[difference,_Pattern|_Blank|_Condition]];
{installSeconds,installed}=AbsoluteTiming[With[{input=difference,result=proof["ExactDifference"]===0},zero[input]=result]];
gate["original generic exact check preserved",And@@(MemberQ[DownValues[zero],#]&/@original)];
{cachedSeconds,cached}=AbsoluteTiming[zero[Total[polynomialAdditivePieces[actual["Equation"]]]-actual["Equation"]]];
gate["cached actual decision equals executed exact proof",cached===(proof["ExactDifference"]===0)];
{ownCachedSeconds,ownCached}=AbsoluteTiming[zero[Total[polynomialAdditivePieces[ownEquation]]-ownEquation]];
gate["own accepted predicate output unchanged",ownCached===ownOriginal&&TrueQ[ownCached]];
gate["measured faster reuse of exact actual identity",cachedSeconds<proof["ExactSeconds"]];
result=<|"Schema"->"polarized-sidis-additive-certificate-cache-v1","Channel"->"Hgg",
 "ProofHash"->FileHash[path,"SHA256"],"NativeVersions"->proof["NativeVersions"],
 "OriginalZeroDefinitions"->original,"CandidateZeroDefinitions"->DownValues[zero],
 "InputHashes"->proof["InputHashes"],"TargetInputHash"->proof["TargetInputHash"],
 "ActualDifferenceHash"->Hash[difference,"SHA256"],"OriginalSeconds"->proof["ExactSeconds"],
 "CachedSeconds"->cachedSeconds,"InstallSeconds"->installSeconds,"OwnOriginalSeconds"->ownOriginalSeconds,
 "OwnCachedSeconds"->ownCachedSeconds,"OwnAcceptedComparison"->True,"ActualAcceptedComparison"->True,"Checks"->checks|>;
dir=FileNameJoin[{root,"Hgg","s08_additive_certificate_cache_result"}];If[!DirectoryQ[dir],CreateDirectory[dir]];
serialized="Uncompress["<>ToString[Compress[result],InputForm]<>"]\n";
Export[FileNameJoin[{dir,"s08_result.wl"}],serialized,"Text"];
gate["exact certificate cache native reload",Get[FileNameJoin[{dir,"s08_result.wl"}]]===result];
Export[FileNameJoin[{dir,"s08_checks.json"}],<|"checks"->checks,"original_seconds"->proof["ExactSeconds"],
 "cached_seconds"->cachedSeconds,"install_seconds"->installSeconds,"own_original_seconds"->ownOriginalSeconds,
 "own_cached_seconds"->ownCachedSeconds,"cached_expression_bytes"->ByteCount[difference],"peak_kernel_memory_bytes"->MaxMemoryUsed[]|>,"RawJSON"];
Print["PASS: s08_Hgg_additive_certificate_reuse"];Quit[0];
